Challenge: code_only_counter.MainWindow.cs:
using System.Windows;
using System.Windows.Controls;

namespace LessonApp;

public class MainWindow : Window
{
    private int count = 0;
    private readonly TextBlock countText;

    public MainWindow()
    {
        Title = "Counter";
        NameScope.SetNameScope(this, new NameScope());
        countText = new TextBlock { Text = "0", Name = "CountText" };
        var addButton = new Button { Content = "Add", Name = "AddButton" };
        addButton.Click += (sender, e) => { count++; countText.Text = count.ToString(); };
        var stack = new StackPanel();
        stack.Children.Add(countText);
        stack.Children.Add(addButton);
        Content = stack;
        RegisterName("CountText", countText);
        RegisterName("AddButton", addButton);
    }
}

Challenge: volume_control.VolumeViewModel.cs:
using System.ComponentModel;

namespace LessonApp;

public class VolumeViewModel : INotifyPropertyChanged
{
    private int volume = 5;

    public VolumeViewModel()
    {
        VolumeUpCommand = new RelayCommand(() => Volume++, () => Volume < 10);
        VolumeDownCommand = new RelayCommand(() => Volume--, () => Volume > 0);
    }

    public int Volume
    {
        get => volume;
        private set
        {
            volume = value;
            PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(nameof(Volume)));
            VolumeUpCommand.RaiseCanExecuteChanged();
            VolumeDownCommand.RaiseCanExecuteChanged();
        }
    }

    public RelayCommand VolumeUpCommand { get; }
    public RelayCommand VolumeDownCommand { get; }

    public event PropertyChangedEventHandler? PropertyChanged;
}

