Challenge: decode_it.Products.cs:
using System.Globalization;

namespace LessonApp;

public record Product(string Name, decimal Price);

public static class ProductExtensions
{
    public static Product WithTax(this Product product, decimal rate) => product with { Price = product.Price * (1 + rate) };

    public static string Label(this Product? product) =>
        product is null ? "(no product)" : $"{product.Name}: {product.Price.ToString("0.00", CultureInfo.InvariantCulture)}";
}

public class Basket
{
    public List<Product> Items { get; } = new();
    public decimal Total => Items.Sum(p => p.Price);
}

