}

Challenge: playlist.Playlist.cs:
using System.Collections;

namespace LessonApp;

public record Song(string Title, int Seconds) : IComparable<Song>
{
    public int CompareTo(Song? other)
    {
        if (other is null) return 1;
        return Seconds != other.Seconds ? Seconds.CompareTo(other.Seconds) : string.Compare(Title, other.Title, StringComparison.Ordinal);
    }
}

public class Playlist : IEnumerable<Song>
{
    private readonly List<Song> songs = new();

    public void Add(Song song) => songs.Add(song);

    public IEnumerator<Song> GetEnumerator() => songs.GetEnumerator();

    IEnumerator IEnumerable.GetEnumerator() => GetEnumerator();
}
